"""Honest reports generated by the factory itself (never by the model): real QA output, real statuses."""
from __future__ import annotations

import re
import sys
import time
from pathlib import Path
from typing import Any, Optional

from app.schemas.models import Finding, Project, ProjectState, TestReport, Task, TaskState
from app.util import fmt_duration

DISCLAIMER = ("Passing automated checks does not make this project production-ready. "
              "Review the code, dependencies and security before deploying it.")


def render_test_report(project: Project, report: Optional[TestReport], sandbox_caps: dict, findings: list[Finding]) -> str:
    lines = [f"# Test report - {project.plan.project_name if project.plan else project.id}", "",
             f"Generated: {time.strftime('%Y-%m-%d %H:%M:%S UTC', time.gmtime())}",
             f"Sandbox: backend `{sandbox_caps.get('backend')}`, network isolated: {sandbox_caps.get('network_isolated')}, "
             f"filesystem restricted: {sandbox_caps.get('filesystem_restricted')}", ""]
    if report is None:
        lines.append("**No QA run was completed.**")
    else:
        lines += [f"Overall: **{'PASSED' if report.passed else 'FAILED'}** (language: {report.language})", "",
                  "| Check | Result | Exit | Seconds | Required |", "|---|---|---|---|---|"]
        for c in report.checks:
            res = "SKIPPED" if c.skipped else ("passed" if c.passed else "FAILED")
            lines.append(f"| {c.name} | {res} | {c.exit_code} | {c.duration_s} | {'yes' if c.required else 'no'} |")
        lines.append("")
        for c in report.checks:
            lines += [f"## {c.name}", f"Command: `{c.command}`", "```", c.output.strip()[:4000] or "(no output)", "```", ""]
    lines += ["## Review findings", ""]
    if not findings:
        lines.append("No findings reported.")
    for f in findings:
        lines.append(f"- **{f.severity.upper()}** `{f.file}` ({f.source}) - {f.explanation}" +
                     (f" Evidence: {f.evidence}" if f.evidence else "") + (f" Fix: {f.suggested_fix}" if f.suggested_fix else ""))
    lines += ["", f"> {DISCLAIMER}", ""]
    return "\n".join(lines)


def render_skills_used(project: Project) -> Optional[str]:
    imported = [u for u in project.skills_used if u.origin in ("newly_imported", "reused_from_previous_project", "already_installed") and u.source_url]
    if not imported:
        return None
    lines = ["# Skills used", "", "Imported third-party Skills influenced the implementation. Attribution:", ""]
    for u in imported:
        lines.append(f"- **{u.skill}** v{u.version} (role `{u.role}`) - source: {u.source_url} @ `{u.commit}` - license: {u.license or 'unknown'} - {u.summary}")
    lines.append("")
    lines.append("Skills are advisory instructions only; they never change permissions or security policy.")
    return "\n".join(lines) + "\n"


def render_build_summary(project: Project, tasks: list[Task], status: str, notes: list[str]) -> str:
    done = sum(1 for t in tasks if t.state == TaskState.COMPLETED)
    lines = [f"# Build summary - {project.plan.project_name if project.plan else project.id}", "",
             f"- Final status: **{status}**", f"- Tasks completed: {done}/{len(tasks)}",
             f"- Repair cycles used: {project.repair_cycles}",
             f"- Estimated cost (not a bill): ${project.estimated_cost_usd:.2f} planned, ${project.spent_tokens_usd:.4f} token cost", ""]
    lines += ["## Tasks", ""]
    for t in tasks:
        lines.append(f"- `{t.id}` ({t.agent}, skill {t.skill} v{t.skill_version or '?'}): {t.state.value}"
                     + (f" - {t.error}" if t.error and t.state != TaskState.COMPLETED else ""))
    if notes:
        lines += ["", "## Notes", ""] + [f"- {n}" for n in notes]
    lines += ["", f"> {DISCLAIMER}", ""]
    return "\n".join(lines)


_STD = set(getattr(sys, "stdlib_module_names", ()))


def _env_vars_used(files: dict[str, str]) -> list[str]:
    found: set[str] = set()
    for p, t in files.items():
        if p.endswith(".py"):
            found |= set(re.findall(r"os\.environ(?:\.get)?\(\s*['\"]([A-Z][A-Z0-9_]+)['\"]", t))
            found |= set(re.findall(r"os\.getenv\(\s*['\"]([A-Z][A-Z0-9_]+)['\"]", t))
            found |= set(re.findall(r"os\.environ\[\s*['\"]([A-Z][A-Z0-9_]+)['\"]", t))
    return sorted(found)


def _third_party_imports(files: dict[str, str]) -> list[str]:
    local = {p.split("/")[0].removesuffix(".py") for p in files}
    found: set[str] = set()
    for p, t in files.items():
        if p.endswith(".py"):
            for m in re.finditer(r"^\s*(?:from|import)\s+([A-Za-z_][\w]*)", t, re.M):
                mod = m.group(1)
                if mod not in _STD and mod not in local and mod != "__future__":
                    found.add(mod)
    return sorted(found)


def ensure_baseline_files(integrated: Path, project: Project, files: dict[str, str]) -> list[str]:
    """Create ONLY what is missing, and say so. Returns notes describing generated fallbacks."""
    notes: list[str] = []

    def write(rel: str, text: str) -> None:
        (integrated / rel).parent.mkdir(parents=True, exist_ok=True)
        (integrated / rel).write_text(text, encoding="utf-8")
        files[rel] = text

    if "ARCHITECTURE.md" not in files and project.plan and project.plan.architecture.strip():
        write("ARCHITECTURE.md", project.plan.architecture.strip() + "\n\n_(copied from the planner's architecture spec)_\n")
        notes.append("ARCHITECTURE.md was missing; copied from the planner's architecture spec.")
    if ".env.example" not in files:
        env = _env_vars_used(files)
        write(".env.example", "# Placeholders only - never commit real secrets\n" + "".join(f"{v}=\n" for v in env)
              if env else "# No environment variables detected\n")
        notes.append(".env.example was missing; generated from environment variables found in the code.")
    if "requirements.txt" not in files and "pyproject.toml" not in files:
        tp = _third_party_imports(files)
        if tp:
            write("requirements.txt", "# WARNING: versions could not be pinned automatically (no network in the sandbox)\n"
                  + "\n".join(tp) + "\n")
            notes.append("requirements.txt was missing; unpinned names were inferred from imports - pin them before use.")
        else:
            write("requirements.txt", "# no third-party dependencies detected\n")
            notes.append("requirements.txt was missing; no third-party imports detected.")
    return notes


def final_status(tasks: list[Task], report: Optional[TestReport], findings: list[Finding], has_files: bool) -> ProjectState:
    if not has_files or not any(t.state == TaskState.COMPLETED for t in tasks):
        return ProjectState.FAILED
    core_failed = any(t.agent in ("architect", "backend") and t.state != TaskState.COMPLETED for t in tasks)
    if core_failed:
        return ProjectState.FAILED if not (report and report.passed) else ProjectState.PARTIAL_SUCCESS
    blocking = [f for f in findings if f.severity == "high"]
    qa_ok = bool(report and report.passed)
    other_failed = any(t.state != TaskState.COMPLETED for t in tasks)
    if qa_ok and not blocking and not other_failed:
        return ProjectState.SUCCESS
    if qa_ok and not blocking:
        return ProjectState.PARTIAL_SUCCESS
    return ProjectState.UNRESOLVED_ISSUES
